SOL={};AUTO={}
def put(code,n,rows,fields=[]):SOL[f'{code}-{n}']=rows;AUTO[f'{code}-{n}']=fields
def N(label,value,tol=1e-9):return {'label':label,'kind':'number','expected':str(value),'tolerance':tol}
def T(label,values,tol=1e-9):return {'label':label,'kind':'tuple','expected':[str(x) for x in values],'tolerance':tol}
def E(label,expr):return {'label':label,'kind':'expression','expected':expr,'variable':'x','tolerance':1e-9}
