put(c,18,[('(a)',3,r'Possible scores $1,2,4,5,6,7$ (1). Probabilities are respectively $1/4,1/4,5/16,1/16,1/16,1/16$ (2); score 4 occurs either immediately or via 3 then 1.'),('(b)',2,fr'$E(X)=\sum xp={mu}$ (1). SD $=\sqrt{{\sum x^2p-\mu^2}}\approx{sqrt(var):.6f}$ (1).'),('(c)',1,r'$E(X)=3.125$, so condition is $X\ge4$; required probability $(5/16)/(8/16)=5/8$ (1).')],[T('(a) probabilities for 1,2,4,5,6,7',ps),N('(b) mean',mu),N('(b) standard deviation',sqrt(var),.0005),N('(c) probability','5/8')])
put(c,19,[('(a)',3,r'Normalisation gives $\int_0^4kt/4\,dt+\int_4^5k\,dt=1$ (1), hence $2k+k=1$ (1), $k=1/3$ (1).'),('(b)',2,r'$E(T)=\int_0^4t^2/12\,dt+\int_4^5t/3\,dt$ (1), $=59/18$ hours beyond the initial 12 hours (1).'),('(c)',3,r'$P(T<a)=0.135$ (1). Since $a<4$, $a^2/24=0.135$ (1), so $a=1.8$ hours (1).')],[N('(a) k','1/3'),N('(b) E(T), hours','59/18'),N('(c) a, hours',1.8)])
r=(1980/(pi*sqrt(2)))**(1/3);area=pi*sqrt(3)*r*r
put(c,20,[('Minimum paper area',7,fr'$\pi r^2h/3=660$ gives $h=1980/(\pi r^2)$ (1). Lateral area $A=\pi r\sqrt{{r^2+h^2}}$ (1), so minimise $A^2=\pi^2r^4+1980^2/r^2$ (1). Differentiate: $4\pi^2r^3-2(1980)^2/r^3=0$ (1), giving $r=(1980/(\pi\sqrt2))^{{1/3}}\approx{r:.5f}$ cm (1). The derivative changes from negative to positive, so this is a minimum (1). Minimum area $\pi\sqrt3r^2\approx{area:.5f}$ cm² (1).')],[N('Minimum paper area, cm²',area,.01)])
put(c,21,[('(a)',3,r'Intersections are $x=0,4$ (1). Area $=\int_0^4[x/(4+x^2)-x/20]dx$ (1), $=\frac12\ln5-2/5$ square units (1).'),('(b)',2,r'A positive second intersection requires $x^2=1/m-4>0$ (1), hence $0<m<1/4$ (1).'),('(c)',2,r'Let $b=\sqrt{1/m-4}$ and integrate to obtain $[\frac12\ln(4+x^2)-mx^2/2]_0^b$ (1). Area $=\frac12\ln(1/(4m))-\frac12+2m$ (1).')],[N('(a) area, square units','.5*ln(5)-.4')])
